import React, { useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';

// --- NAVBAR ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3">
          <div className="bg-orange-600 p-2 rounded-full shadow-md flex items-center justify-center">
            <svg width="24" height="24" viewBox="0 0 512 512" fill="white" xmlns="http://www.w3.org/2000/svg">
              <path d="M416 0c-35.3 0-64 28.7-64 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80z" />
            </svg>
          </div>
          <span className="font-black text-xl tracking-tighter text-gray-900 uppercase italic">Fast<span className="text-orange-600">Délice</span></span>
        </Link>

        <div className="flex items-center space-x-4">
          <Link to="/register" className="bg-gray-900 text-white px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-orange-600 transition shadow-lg">
            S'inscrire
          </Link>
          <Link to="/login" className="bg-orange-600 text-white px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest hover:bg-gray-900 transition shadow-lg">
            Connexion
          </Link>
        </div>
      </div>
    </nav>
  );
};

// --- REGISTER PAGE ---
const Register = () => {
  const [formData, setFormData] = useState({ name: '', email: '', password: '' });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      // Hna k-n-sifto l-data l-Django nishan
      await axios.post('http://127.0.0.1:8000/menu/register/', formData); 
      alert("Account created successfully! You can now login.");
    } catch (err) {
      alert("Error: Email already exists or server is down.");
    }
  };

  return (
    <div className="min-h-screen bg-black flex items-center justify-center p-6">
      <div className="max-w-md w-full bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        <h2 className="text-white text-3xl font-black uppercase tracking-tighter mb-8 text-center">Créer un Compte</h2>
        <form className="space-y-6" onSubmit={handleSubmit}>
          <input 
            type="text" 
            placeholder="NOM COMPLET" 
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold uppercase"
            onChange={(e) => setFormData({...formData, name: e.target.value})}
            required
          />
          <input 
            type="email" 
            placeholder="EMAIL" 
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold"
            onChange={(e) => setFormData({...formData, email: e.target.value})}
            required
          />
          <input 
            type="password" 
            placeholder="MOT DE PASSE" 
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold"
            onChange={(e) => setFormData({...formData, password: e.target.value})}
            required
          />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition shadow-lg">
            S'inscrire
          </button>
        </form>
      </div>
    </div>
  );
};

// --- APP COMPONENT ---
function App() {
  return (
    <Router>
      <Navbar cartCount={0} />
      <Routes>
        <Route path="/register" element={<Register />} />
        {/* Zidi l-routes l-khrin hna */}
      </Routes>
    </Router>
  );
}

export default App;
